    sorted_vals = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    sep_color = sorted_vals[1][0] if len(sorted_vals) >= 2 else 0

    # Find all row indices containing markers (values != block and != sep)
    marker_row_indices = set()
    for r in range(h):
        for c in range(w):
