                marker_row_indices.add(r)

    if not marker_row_indices:
        return [[block_color] * w for _ in range(h)]

    # Find all column indices containing markers
    marker_col_indices = set()
    for c in range(w):
        for r in range(h):
            if grid[r][c] != block_color and grid[r][c] != sep_color:
                marker_col_indices.add(c)
                break

    if not marker_col_indices:
        return [[block_color] * w for _ in range(h)]

    # Build output from marker positions
    sorted_rows = sorted(marker_row_indices)
    sorted_cols = sorted(marker_col_indices)

    row_map = {r: i for i, r in enumerate(sorted_rows)}
    col_map = {c: i for i, c in enumerate(sorted_cols)}

